checks.solution:
def propagate(domains, neighbours, allowed, seeds):
    out = {node: set(values) for node, values in domains.items()}
    for node in out:
        if not out[node]:
            raise ValueError(f"{node!r} started with no options")
    queue = list(seeds)
    for node in queue:
        if node not in out:
            raise ValueError(f"unknown node {node!r}")
    while queue:
        node = queue.pop()
        for direction, other in neighbours.get(node, {}).items():
            if other not in out:
                raise ValueError(f"unknown node {other!r}")
            table = allowed[direction]
            supported = set()
            for value in out[node]:
                supported |= table.get(value, set())
            survivors = out[other] & supported
            if survivors == out[other]:
                continue
            if not survivors:
                raise ValueError(f"contradiction at {other!r}")
            out[other] = survivors
            queue.append(other)
    return out

checks.test:
# Three cells in a row. Land may touch land or coast; coast touches anything;
# sea may touch sea or coast -- but land and sea may never touch.
TOUCH = {"L": {"L", "C"}, "C": {"L", "C", "S"}, "S": {"C", "S"}}
ALLOWED = {"E": TOUCH, "W": TOUCH}
LINE = {
    "a": {"E": "b"},
    "b": {"W": "a", "E": "c"},
    "c": {"W": "b"},
}
ALL = {"a": {"L", "C", "S"}, "b": {"L", "C", "S"}, "c": {"L", "C", "S"}}

# Nothing has been decided: the constraints are already satisfied, so nothing changes.
assert propagate(ALL, LINE, ALLOWED, []) == ALL
assert propagate(ALL, LINE, ALLOWED, ["b"]) == ALL

# Collapse the left cell to land: its neighbour loses sea, and the ripple stops there
# because the middle cell can still be coast, which supports anything.
start = dict(ALL, a={"L"})
out = propagate(start, LINE, ALLOWED, ["a"])
assert out["a"] == {"L"}, out
assert out["b"] == {"L", "C"}, out
assert out["c"] == {"L", "C", "S"}, out

# The input is untouched -- a caller must be able to keep the pre-propagation state.
assert start["b"] == {"L", "C", "S"}, "propagate must not mutate its input"

# Now force the middle cell to land as well: the ripple reaches two cells away.
out = propagate(dict(ALL, a={"L"}, b={"L"}), LINE, ALLOWED, ["a", "b"])
assert out["c"] == {"L", "C"}, out

# A ripple that travels the whole line: with only land and sea available, forcing one
# end forces every cell, because nothing can bridge them.
STRICT = {"a": {"L", "S"}, "b": {"L", "S"}, "c": {"L", "S"}}
out = propagate(dict(STRICT, a={"S"}), LINE, ALLOWED, ["a"])
assert out == {"a": {"S"}, "b": {"S"}, "c": {"S"}}, out

# A contradiction: two incompatible cells pinned at the ends of a two-cell world.
PAIR = {"a": {"E": "b"}, "b": {"W": "a"}}
for bad in ({"a": {"L"}, "b": {"S"}}, {"a": {"S"}, "b": {"L"}}):
    try:
        propagate(bad, PAIR, ALLOWED, list(bad))
    except ValueError:
        continue
    raise AssertionError(f"must be a contradiction: {bad}")

# ...and one that only appears after the ripple travels, not at the collapsed cell.
CHAIN = {"a": {"S"}, "b": {"L", "S"}, "c": {"L"}}
try:
    propagate(CHAIN, LINE, ALLOWED, ["a", "c"])
except ValueError:
    pass
else:
    raise AssertionError("a contradiction two cells away must still be found")

# An empty domain on the way in, and an unknown node, are both refused.
for bad_call in ((dict(ALL, b=set()), LINE, ALLOWED, ["a"]),
                 (ALL, LINE, ALLOWED, ["zzz"])):
    try:
        propagate(*bad_call)
    except ValueError:
        continue
    raise AssertionError("must be rejected")
